export interface Widget {
  id: string;
  title: string;
  position: number;
}

export interface LayoutApi {
  widgets(userId: string): Promise<Widget[]>;
  hiddenIds(userId: string): Promise<string[] | null>;
  saveLayout(userId: string, widgets: Widget[]): Promise<void>;
}

export async function loadVisible(api: LayoutApi, userId: string): Promise<Widget[]> {
  const [widgets, hiddenIds] = await Promise.all([
    api.widgets(userId),
    api.hiddenIds(userId),
  ]);
  const hidden = new Set(hiddenIds ?? []);
  return widgets.filter((widget) => !hidden.has(widget.id));
}

export function ordered(widgets: Widget[]): Widget[] {
  return [...widgets].sort((a, b) => a.position - b.position);
}

export function topThree(widgets: Widget[]): Widget[] {
  return ordered(widgets).slice(0, 3);
}

export async function moveWidget(
  api: LayoutApi,
  userId: string,
  widgetId: string,
  position: number,
): Promise<Widget[]> {
  const widgets = await api.widgets(userId);
  if (!widgets.some((widget) => widget.id === widgetId)) {
    throw new Error(`Unknown widget ${widgetId}`);
  }
  const moved = widgets.map((widget) =>
    widget.id === widgetId ? { ...widget, position } : widget,
  );
  const result = ordered(moved);
  await api.saveLayout(userId, result);
  return result;
}
